package com.novalearn.infrastructure.persistence;
import com.novalearn.application.auth.*; import com.novalearn.application.child.ChildProfileRepository; import com.novalearn.application.progress.LessonProgressRepository; import com.novalearn.application.rewards.ChildRewardsRepository; import com.novalearn.domain.child.ChildProfile; import com.novalearn.domain.progress.LessonProgress; import com.novalearn.domain.rewards.ChildRewards; import org.springframework.stereotype.Repository; import java.util.*;
@Repository class JpaParentAccountAdapter implements ParentAccountRepository {
 private final ParentAccountJpaRepository repo; JpaParentAccountAdapter(ParentAccountJpaRepository repo){this.repo=repo;} public boolean existsByEmail(String e){return repo.existsByEmail(e);} public ParentAccount save(ParentAccount a){ParentAccountEntity e=repo.save(new ParentAccountEntity(a.id(),a.email(),a.passwordHash(),a.role()));return new ParentAccount(e.getId(),e.getEmail(),e.getPasswordHash(),e.getRole());} public Optional<ParentAccount> findByEmail(String email){return repo.findByEmail(email).map(e->new ParentAccount(e.getId(),e.getEmail(),e.getPasswordHash(),e.getRole()));}}
@Repository class JpaChildProfileAdapter implements ChildProfileRepository {
 private final ChildProfileJpaRepository repo; JpaChildProfileAdapter(ChildProfileJpaRepository repo){this.repo=repo;} public ChildProfile save(ChildProfile p){ChildProfileEntity e=repo.save(new ChildProfileEntity(p.id(),p.parentId(),p.displayName(),p.birthDate()));return map(e);} public List<ChildProfile> findByParentId(UUID p){return repo.findByParentIdOrderByDisplayNameAsc(p).stream().map(JpaChildProfileAdapter::map).toList();} public boolean belongsToParent(UUID c,UUID p){return repo.existsByIdAndParentId(c,p);} private static ChildProfile map(ChildProfileEntity e){return new ChildProfile(e.getId(),e.getParentId(),e.getDisplayName(),e.getBirthDate());}}
@Repository class JpaLessonProgressAdapter implements LessonProgressRepository {
 private final LessonProgressJpaRepository repo; JpaLessonProgressAdapter(LessonProgressJpaRepository repo){this.repo=repo;} public Optional<LessonProgress> findByChildIdAndLessonCode(UUID c,String l){return repo.findByChildIdAndLessonCode(c,l).map(JpaLessonProgressAdapter::map);} public LessonProgress save(LessonProgress p){return map(repo.save(new LessonProgressEntity(p.id(),p.childId(),p.lessonCode(),p.score(),p.completed(),p.updatedAt())));} public List<LessonProgress> findByChildId(UUID c){return repo.findByChildIdOrderByUpdatedAtDesc(c).stream().map(JpaLessonProgressAdapter::map).toList();} private static LessonProgress map(LessonProgressEntity e){return new LessonProgress(e.getId(),e.getChildId(),e.getLessonCode(),e.getScore(),e.isCompleted(),e.getUpdatedAt());}}
@Repository class JpaChildRewardsAdapter implements ChildRewardsRepository {
 private final ChildRewardsJpaRepository repo; JpaChildRewardsAdapter(ChildRewardsJpaRepository repo){this.repo=repo;}
 public Optional<ChildRewards> findByChildId(UUID childId){return repo.findById(childId).map(JpaChildRewardsAdapter::map);}
 public ChildRewards save(ChildRewards rewards){ChildRewardsEntity e=repo.save(new ChildRewardsEntity(rewards.childId(),rewards.coins(),rewards.currentStreak(),rewards.longestStreak(),rewards.lastActivityDate()));return map(e);}
 private static ChildRewards map(ChildRewardsEntity e){return new ChildRewards(e.getChildId(),e.getCoins(),e.getCurrentStreak(),e.getLongestStreak(),e.getLastActivityDate());}}
